import {applyFont,fontName,localFonts,safeBackground} from './theme-runtime.js';
import {displayToggles,normalizeTheme,exportBetterCampus,communityRequest} from './theme-compat.js';
import {uid,dayKey,themes,initial,legalVersion,mergeImport,recordActivity,streak,gpaSummary,requiredFinal,assignmentGrade,activeTheme,studyFromText,calendarICS,calendarLink,safeURL,embedURL} from './core.js';
import {read,write,filePut,fileGet,fileDelete,fileKeys,filePrune,fileClear,readCompanionToken,writeCompanionToken} from './store.js';
import {startGame} from './games.js';
import {clearDeviceSync} from './device-sync.js';
import {readSync,writeSync,clearSync,providerOrigins,configured,authorize} from './calendar-sync.js';
if (window.top !== window) {
  const parentOrigin = location.ancestorOrigins?.[0];
  const allowed = parentOrigin && (await read()).settings.lmsOrigins.includes(parentOrigin) && await chrome.permissions.contains({origins:[parentOrigin+'/*']});
  if (!allowed) { document.body.textContent='CourseLark can only open inside a connected LMS tab.'; throw Error('Unconnected page attempted to embed CourseLark.'); }
}
let calendarState=globalThis.chrome?.identity?await readSync():null;
let state=await read(),section='',studyIndex=0,studyFlipped=false,quizAnswered=false,timerInterval,recorder,recognition,recordParts=[],recordStream;
const view=document.querySelector('#view'),dialog=document.querySelector('#dialog'),body=document.querySelector('#dialog-body');
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const btn=(label,action,id='',cls='secondary')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const empty=message=>`<div class="empty">${message}</div>`;
const courseName=id=>state.courses.find(c=>c.id===id)?.name||'Personal';
const courseOptions=selected=>`<option value="">Personal</option>`+state.courses.map(c=>`<option value="${esc(c.id)}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('');
const dateLabel=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'No due date';
const localDate=value=>{if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const nullableDate=value=>value?new Date(value).toISOString():'';
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.hidden=true,4500);}
function notice(message){const n=document.querySelector('#notice');n.textContent=message;n.hidden=!message;}
async function persist(render=false){await write(state);applyTheme();if(render)draw();}
function applyTheme(){let settings=state.settings;if(settings.rotate){const list=[settings.theme,...state.themes];settings={...settings,theme:list[Math.floor(Date.now()/86400000)%list.length]};}const t=activeTheme(settings,new Date(),matchMedia('(prefers-color-scheme: dark)').matches);for(const [key,value] of Object.entries({bg:t.bg,surface:t.surface,text:t.text,accent:t.accent}))if(/^#[\da-f]{6}$/i.test(value))document.documentElement.style.setProperty('--'+key,value);document.body.style.fontFamily=applyFont(document,t.font);document.querySelector('#sidebar').style.background=safeBackground(t.sidebar)||t.surface;document.documentElement.style.colorScheme=t.dark?'dark':'light';}
const pages=[['dashboard','◫','Overview'],['tasks','✓','Assignments'],['planner','▦','Planner'],['grades','↗','Grades & GPA'],['notes','▤','Notebooks'],['study','◇','Study sets'],['themes','◐','Appearance'],['focus','◷','Focus room'],['settings','⚙','Settings']];
document.querySelector('#nav').innerHTML=pages.map(([id,icon,label])=>`<a href="#${id}" data-page="${id}"><span aria-hidden="true">${icon}</span>${label}</a>`).join('');
document.querySelector('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();
document.querySelector('#theme-toggle').onclick=async()=>{if(state.legalAcceptance?.version!==legalVersion)return;state.settings.mode=state.settings.mode==='dark'?'light':'dark';await persist();};
document.querySelector('#close-dialog').onclick=()=>dialog.close();
window.addEventListener('hashchange',draw);if(globalThis.chrome?.storage)chrome.storage.onChanged.addListener(async changes=>{if(changes.campus?.newValue&&changes.campus.newValue.revision!==state.revision){state=changes.campus.newValue;applyTheme();if(!dialog.open)draw();}});
function draw(){section=location.hash.slice(1)||'dashboard';if(!pages.some(p=>p[0]===section))section='dashboard';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===section));document.querySelector('#title').textContent=section==='dashboard'?'Your campus, at your pace.':pages.find(p=>p[0]===section)[2];if(state.legalAcceptance?.version!==legalVersion){view.innerHTML=`<div class="card" style="max-width:680px"><h2>Before you continue</h2><p><strong>Data in this browser:</strong> After you enable a school site, CourseLark automatically stores your Canvas profile identifier, courses, assignments, grades, recent announcements, and any notes, files, and study activity you add in this browser. It does not send these records to Noah Fishman.</p><p><strong>Optional transfers:</strong> AI, browser speech, calendar links and calendar sync, and custom images may contact outside services when you choose those features.</p><p>Read the <a href="legal/terms.html" target="_blank" rel="noopener">Terms of Use</a> and <a href="legal/privacy.html" target="_blank" rel="noopener">Privacy Policy</a>. By selecting Agree and continue, you agree to the Terms of Use. This agreement does not replace any permission required for a child to use optional services.</p><div class="row">${btn('Agree and continue','legal-accept','','')}${btn('Export existing data','backup-export')}${btn('Erase local data','data-clear')}</div></div>`;return;}const renderers={dashboard,tasks,planner,grades,notes,study,themes:themePage,focus,settings};view.innerHTML=renderers[section]();if(section==='focus')refreshTimer();}
function sortedTasks(){return [...state.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||(Date.parse(a.due)||Infinity)-(Date.parse(b.due)||Infinity));}
function taskRows(list){return list.length?list.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task-check="${esc(t.id)}" aria-label="Complete ${esc(t.title)}" ${t.done?'checked':''}><div class="task-info"><strong>${esc(t.title)}</strong><small>${esc(courseName(t.courseId))} · ${esc(dateLabel(t.due))} ${!t.done&&t.due&&Date.parse(t.due)<Date.now()?'· Overdue':''}</small>${t.subtasks?.length?`<small>${t.subtasks.filter(s=>s.done).length}/${t.subtasks.length} subtasks</small>`:''}</div>${btn('↗','task-preview',t.id,'ghost')}${btn('Edit','task-edit',t.id,'ghost')}</div>`).join(''):empty('A little breathing room. Add an assignment to get started.');}
function dashboard(){const done=state.tasks.filter(t=>t.done).length,total=state.tasks.length,progress=total?Math.round(done/total*100):0,xp=state.activity.reduce((n,a)=>n+a.xp,0),grade=gpaSummary(state,{...state.settings}).cumulative.gpa;return `<div class="hero"><div><span class="eyebrow" style="color:inherit">A SPACE THAT WORKS FOR YOU</span><h2>Find your rhythm.</h2><p>A clear plan, a quiet mind, one thing at a time.</p>${btn('＋ Add assignment','task-edit','','secondary')}</div><div class="ring" style="--progress:${progress};--accent:#f1dab0;--border:#ffffff30"><span style="background:var(--accent);color:var(--text)">${progress}%</span></div></div><div class="grid stats"><div class="card"><small>Upcoming assignments</small><div class="stat">${state.tasks.filter(t=>!t.done).length}</div><small>${done} completed · All classes in one place</small></div><div class="card"><small>Your GPA</small><div class="stat">${grade===null?'—':grade.toFixed(2)}</div><small>Credit-weighted · ${esc(state.settings.gpaScale==='plusMinus'?'Plus/minus':state.settings.gpaScale==='custom'?'Custom':'Whole-letter')} scale</small></div><div class="card"><small>Study streak</small><div class="stat">${streak(state)} <span style="font-size:17px">days</span></div><small>Keep showing up for yourself</small></div></div><div class="two"><div class="stack"><div class="card"><div class="row between"><h2>Up next</h2><a href="#tasks">View all →</a></div>${taskRows(sortedTasks().filter(t=>!t.done).slice(0,5))}</div><div><div class="toolbar"><h2>Your classes</h2>${btn('＋ Add class','course-edit','','ghost')}</div><div class="grid">${courseCards()}</div></div></div><div class="stack"><div class="card" ${state.settings.showCompanion===false?'hidden':''} style="text-align:center"><span class="badge">YOUR STUDY COMPANION</span><div class="pet" role="img" aria-label="An original sprout companion"></div><h2>Sprout · Level ${1+Math.floor(xp/100)}</h2><p class="muted">Grows with every small win.</p><div class="progressbar"><span style="width:${xp%100}%"></span></div><small>${xp%100} / 100 XP to the next level</small></div><div class="card" ${state.settings.showQuote===false?'hidden':''}><h3>A thought for today</h3><p class="quote">${esc(state.settings.quote)}</p><a href="#focus">Step into your focus room →</a></div>${announcementCard()}<div class="card"><h3>Connect your classes</h3><p class="muted">Open your signed-in LMS tab and choose Enable on this site in the extension popup once.</p><small>Canvas assignments and grades then sync automatically when you visit.</small></div></div></div>`;}
function courseCards(){return state.courses.length?state.courses.map((c,i)=>`<article class="card"><div class="course-banner" style="background:linear-gradient(125deg,${/^#[\da-f]{6}$/i.test(state.settings.theme.palette?.[i%4])?state.settings.theme.palette[i%4]:'#86a98d'},var(--accent))"></div><small>${esc(c.code||'YOUR CLASS')}</small><h3>${esc(c.name)}</h3><div class="course-footer row between"><span>${c.grade==null?'No grade yet':Number(c.grade).toFixed(1)+'%'}</span>${btn('Manage','course-edit',c.id,'ghost')}</div></article>`).join(''):empty('Add a class or import from Canvas.');}
function tasks(){return `<div class="toolbar"><p class="muted">Every deadline. One clear list.</p><div class="row"><input id="task-search" placeholder="Search assignments" aria-label="Search assignments"><select id="task-filter" aria-label="Filter assignments"><option value="open">Upcoming</option><option value="all">All assignments</option><option value="done">Completed</option><option value="today">Due today</option></select>${btn('＋ Add assignment','task-edit','','')}</div></div><div class="card" id="task-list">${taskRows(sortedTasks().filter(t=>!t.done))}</div>`;}
function planner(){const list=sortedTasks().filter(t=>!t.done);const days=new Map();for(const t of list){const key=(t.workStart||t.due)?dayKey(t.workStart||t.due):'Unscheduled';if(!days.has(key))days.set(key,[]);days.get(key).push(t);}return `<div class="toolbar"><p class="muted">Give your work a time and a place.</p><div class="row">${btn('Export calendar (.ics)','calendar-export')}${btn('＋ Add work block','task-edit','','')}</div></div>${calendarCard()}<div class="stack" style="margin-top:18px">${[...days].sort(([a],[b])=>a.localeCompare(b)).map(([day,list])=>`<div class="card"><h2>${esc(day)}</h2>${list.map(t=>`<div class="task"><div class="task-info"><strong>${esc(t.title)}</strong><small>${t.workStart?'Work block: '+esc(dateLabel(t.workStart))+' – '+esc(new Date(t.workEnd||Date.parse(t.workStart)+Number(t.minutes||30)*60000).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})):'Due: '+esc(dateLabel(t.due))}</small></div>${btn('Schedule','task-edit',t.id,'ghost')}${btn('Google','calendar-google',t.id,'ghost')}${btn('Outlook','calendar-outlook',t.id,'ghost')}</div>`).join('')}</div>`).join('')||empty('Add your first assignment or work block.')}</div>`;}
function grades(){const summary=gpaSummary(state,{...state.settings}),college=summary.cumulative.gpa,current=summary.current.gpa;return `<div class="toolbar"><p class="muted">Know where you stand. Explore what comes next.</p>${btn('＋ Add class','course-edit','','')}</div><div class="grid stats"><div class="card"><small>Current term GPA</small><div class="stat">${current==null?'—':current.toFixed(2)}</div><small>${esc(summary.selectedTerm?.name||'No active term detected')}</small></div><div class="card"><small>Cumulative GPA</small><div class="stat">${college==null?'—':college.toFixed(2)}</div><small>${summary.cumulative.credits} credits · ${esc(summary.scale)} scale</small></div><div class="card"><small>Grade goals</small><div class="stat">${state.courses.filter(c=>c.grade!=null&&c.grade>=c.goal).length}/${state.courses.length}</div></div></div><div class="card overflow"><table><thead><tr><th>Class</th><th>Current</th><th>Credits</th><th>Goal</th><th>Tools</th></tr></thead><tbody>${state.courses.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.grade==null?'—':Number(c.grade).toFixed(1)+'%'}</td><td>${esc(c.credits)}</td><td>${esc(c.goal)}%</td><td>${btn('What if?','what-if',c.id,'ghost')}${btn('Assignments','assignment-grades',c.id,'ghost')}${btn('Edit','course-edit',c.id,'ghost')}</td></tr>`).join('')}</tbody></table>${state.courses.length?'':empty('Add classes with grades and credits to calculate your GPA.')}</div><div class="grid" style="margin-top:20px">${state.courses.filter(c=>c.history?.length).map(c=>`<div class="card"><h3>${esc(c.name)} · trend</h3><div class="chart">${c.history.slice(-12).map(h=>`<span style="height:${Math.max(2,Math.min(100,Number(h.grade)))}%" title="${esc(h.day)}: ${esc(h.grade)}%"></span>`).join('')}</div><small>${c.history.length} grade snapshots</small></div>`).join('')}</div><p class="muted" style="margin-top:20px;font-size:12px">GPA uses the documented default scale in README. Your school’s grading rules may differ. What-if calculations do not change official grades.</p>`;}
function notes(){return `<div class="toolbar"><p class="muted">Keep the ideas. Make the connections.</p>${btn('＋ New note','note-edit','','')}</div><div class="grid">${state.notes.map(n=>`<article class="card"><span class="badge">${esc(courseName(n.courseId))}</span><h2 style="margin-top:14px">${esc(n.title)}</h2><p class="note-body">${esc(n.body)}</p><small>${(n.files||[]).length} files · ${new Date(n.updated||Date.now()).toLocaleDateString()}</small><div class="row" style="margin-top:16px">${btn('Open notebook','note-edit',n.id)}${btn('Study this','note-study',n.id,'ghost')}</div></article>`).join('')||empty('Create your first notebook. Write, record, import files, and turn notes into study sets.')}</div>`;}
function study(){return `<div class="toolbar"><p class="muted">Practice a little. Remember a lot.</p>${btn('＋ New study set','set-edit','','')}</div><div class="grid">${state.sets.map(s=>`<article class="card"><span class="badge">${esc(courseName(s.courseId))}</span><h2 style="margin-top:14px">${esc(s.title)}</h2><p class="muted">${s.cards.length} cards · ${s.sessions||0} practice sessions</p><div class="row">${btn('Flashcards','study-flash',s.id,'')}${btn('Quiz','study-quiz',s.id)}${btn('Edit','set-edit',s.id,'ghost')}</div><div class="row" style="margin-top:12px">${['Match','Blocks','Blast','Charms'].map(g=>btn(g,'game-'+g.toLowerCase(),s.id,'ghost')).join('')}</div></article>`).join('')||empty('Build a set from a notebook, or add your own terms and definitions.')}</div>`;}
function themePage(){return `<div class="toolbar"><p class="muted">A campus that feels like you.</p><div class="row">${btn('Import theme','theme-import')}${btn('Paste theme JSON','theme-paste')}${btn('Community themes','theme-community')}${btn('＋ Create theme','theme-edit','','')}</div></div><div class="grid">${[...themes,...state.themes].map(t=>`<article class="card"><div style="height:90px;border-radius:12px;background:${/^#[\da-f]{6}$/i.test(t.bg)?t.bg:'#ddd'};padding:16px;border:1px solid var(--border)"><div style="height:16px;width:60%;border-radius:5px;background:${/^#[\da-f]{6}$/i.test(t.accent)?t.accent:'#444'}"></div><div class="swatches">${(t.palette||[]).map(c=>`<span style="background:${/^#[\da-f]{6}$/i.test(c)?c:'#ddd'}"></span>`).join('')}</div></div><h3 style="margin-top:14px">${esc(t.name)}</h3><small>${esc(t.font)} · ${t.dark?'Dark':'Light'}${t.credits?' · by '+esc(t.credits):''}</small><div class="row" style="margin-top:14px">${btn('Apply','theme-apply',t.id,'')}${btn('Remix','theme-edit',t.id,'ghost')}${btn('Export','theme-export',t.id,'ghost')}${btn('BetterCampus export','theme-export-better',t.id,'ghost')}${state.themes.some(x=>x.id===t.id)?btn('Delete','theme-delete',t.id,'ghost'):''}</div></article>`).join('')}</div><div class="card" style="margin-top:24px"><h2>Display settings</h2><form id="display-form" class="form-grid"><label>Mode<select name="mode">${['light','dark','system','schedule'].map(m=>`<option ${state.settings.mode===m?'selected':''}>${m}</option>`).join('')}</select></label><label>Font family<input name="font" maxlength="80" value="${esc(state.settings.font)}" required><small>Installed fonts or a Google Fonts family, e.g. Jost.</small></label><label>Dark mode begins<input type="time" name="darkStart" value="${esc(state.settings.darkStart)}" required></label><label>Dark mode ends<input type="time" name="darkEnd" value="${esc(state.settings.darkEnd)}" required></label>${displayToggles.map(([id,label])=>`<label class="check"><input type="checkbox" name="${id}" ${(state.settings[id]??initial().settings[id])?'checked':''}>${label}</label>`).join('')}<label>Assignments per course card<input type="number" name="assignmentCount" min="1" max="20" value="${state.settings.assignmentCount??3}" required></label><label class="wide">Custom CSS<textarea name="customCSS" rows="6" maxlength="20000" spellcheck="false" placeholder=".ic-DashboardCard { border-radius: 18px; }">${esc(state.settings.customCSS||'')}</textarea><small>Applied last on connected LMS pages. Images or fonts referenced with url() load from their hosts.</small></label><button class="wide">Save display settings</button></form></div><div class="card" style="margin-top:18px"><h2>Theme history</h2><div class="row">${state.themeHistory.slice().reverse().map((t,i)=>btn(esc(t.name),'theme-history',state.themeHistory.length-1-i,'ghost')).join('')||'<small>No theme switches yet.</small>'}</div></div><div class="card" style="margin-top:18px"><h2>Course card editor</h2><p class="muted">Colors, image backgrounds, brightness and blur for each imported class.</p><div class="row">${state.courses.map(c=>btn(esc(c.name),'card-edit',c.id)).join('')||'<small>Add or import classes first.</small>'}</div></div>`;}
function focus(){return `<div class="two"><div class="stack"><div class="card"><span class="badge">ONE THING AT A TIME</span><h2 style="margin-top:14px">Focus timer</h2><div class="timer" id="timer-display">25:00</div><div class="row" style="justify-content:center">${btn('Start / Pause','timer-toggle','','')}${btn('Reset','timer-reset')}${btn('Break','timer-break')}</div><form id="timer-form" class="form-grid" style="margin-top:24px"><label>Focus minutes<input name="focusMinutes" type="number" min="1" max="240" value="${state.settings.focusMinutes}" required></label><label>Break minutes<input name="breakMinutes" type="number" min="1" max="120" value="${state.settings.breakMinutes}" required></label><button class="wide secondary">Save intervals</button></form></div><div class="card"><h2>Study soundtrack</h2><p class="muted">Save your own Spotify, Apple Music or YouTube playlist link.</p><form id="playlist-form" class="row"><input name="playlist" type="url" placeholder="https://…" value="${esc(state.settings.playlist)}" style="flex:1"><button>Save</button></form>${safeURL(state.settings.playlist)?`<p style="margin-top:16px"><a href="${esc(safeURL(state.settings.playlist))}" target="_blank" rel="noopener">Open your playlist ↗</a>${embedURL(state.settings.playlist)?` · ${btn('Play here','playlist-embed','','ghost')}`:''}</p><div id="playlist-player"></div>`:''}</div></div><div class="stack"><div class="card" style="text-align:center"><h2>A breathing break</h2><p class="muted" id="breath-label">In for four. Out for four.</p><div class="breath" id="breath-circle"></div><label>Duration (seconds)<input type="number" id="breath-duration" value="${state.settings.breathSeconds}" min="8" max="600"></label><div style="margin-top:20px">${btn('Begin breathing','breath','','')}</div></div><div class="card"><p class="quote">${esc(state.settings.quote)}</p><form id="quote-form"><label>Your motivation quote<textarea name="quote" required>${esc(state.settings.quote)}</textarea></label><button class="secondary" style="margin-top:10px">Save quote</button></form></div></div></div>`;}
function settings(){return `<div class="stack"><div class="card"><h2>Your data, your device.</h2><p class="muted">No CourseLark account or tracking. Your notes, tasks, grades, and files stay in browser storage unless you choose to export them or use an external service. Make regular backups.</p><div class="row">${btn('Export backup','backup-export')}${btn('Import backup','backup-import')}${btn('Erase local data','data-clear')}</div><small>Backup includes notes, tasks, study sets, settings, and themes. Audio and attached file blobs have separate exports in each notebook.</small></div>${globalThis.chrome?.storage?.sync?`<div class="card"><h2>Sync across devices</h2><p class="muted">Keep settings, themes and appearance the same in every browser signed in to the same browser account. This uses your browser’s own sync (for Chrome, your Google Account); there is no CourseLark server. Tasks, grades, notes, files and connected sites stay on each device.</p><form id="device-sync-form" class="row"><label class="check"><input type="checkbox" name="syncAcrossDevices" ${state.settings.syncAcrossDevices?'checked':''}>Sync settings and themes</label><button>Save</button></form><small>Turning it on adopts settings already synced from another device. Erase local data also removes the synced copy.</small></div>`:''}<div class="card"><h2>Assignment reminders</h2><form id="reminder-form" class="row"><label class="check"><input type="checkbox" name="reminders" ${state.settings.reminders?'checked':''}>Desktop reminders</label><label>Minutes before deadline<input name="reminderMinutes" type="number" value="${state.settings.reminderMinutes}" min="5" max="10080" required></label><button>Save</button></form><p class="muted" style="margin-top:15px">Checks once a minute while the browser is open. System notification settings apply.</p></div><div class="card"><h2>AI through Ollama</h2><p class="muted">AI actions send selected notes and prompts to the companion on this device, which forwards them to your configured Ollama service. Ollama may process them in the cloud if you choose a cloud model. The app does not verify local-only mode. No paid API is included.</p><form id="pairing-form" class="row"><label>Companion pairing code<input name="pairingToken" type="password" autocomplete="off" placeholder="Paste code from companion terminal" required></label><button>Pair browser</button></form><small>The code is stored only in this browser profile, outside exported backups. A new code is shown each time the companion starts unless you set CAMPUS_PAIRING_TOKEN.</small><form id="ai-form" class="row"><label>Ollama model name<input name="model" value="${esc(state.settings.model)}" required></label><button>Save</button>${btn('Check AI connection','ai-test')}</form><p class="muted" style="margin-top:16px">Start the companion with <code>node server.mjs</code>. For on-device processing, use a downloaded model and disable Ollama cloud features. Check AI output against your original sources.</p></div><div class="card"><h2>Connected LMS sites</h2><p class="muted">Enable sites from the extension popup on the school tab. Only approved sites receive the content script, and Canvas data refreshes automatically when you visit them.</p>${state.settings.lmsOrigins.map(o=>`<div class="row between"><code>${esc(o)}</code>${btn('Disconnect','disconnect',o,'ghost')}</div>`).join('')||'<small>No sites connected yet.</small>'}</div><div class="card"><h2>Legal and support</h2><p>Read the <a href="legal/terms.html" target="_blank" rel="noopener">Terms of Use</a> and <a href="legal/privacy.html" target="_blank" rel="noopener">Privacy Policy</a>. Original project code is offered under the <a href="https://github.com/cedarRed123/open-campus/blob/main/LICENSE" target="_blank" rel="noopener">MIT license</a>; bundled components have separate notices.</p><small>For support, use ntfishman@gmail.com. GitHub issues are public: do not post student records, full backups, or recordings.</small></div><div class="card"><h2>Project coverage</h2><p>This is an independent implementation with local replacements. Google Classroom import, theme publishing/reactions, friends, and syncing tasks/notes across devices are not implemented. Settings and themes can sync through your browser account. Calendar sync to Google, Outlook and iCloud is available in Planner. Public community themes can be browsed and imported from Appearance. See FEATURE-COVERAGE.md for the full status.</p></div></div>`;}
function announcementCard(){if(!(state.settings.showAnnouncements??true))return '';const active=a=>!a.sourceOrigin||!state.settings.activeAccounts?.[a.sourceOrigin]||String(state.settings.activeAccounts[a.sourceOrigin])===String(a.userId);const list=(state.announcements||[]).filter(active).slice(0,5);if(!list.length)return '';return `<div class="card"><h3>Announcements</h3>${list.map(a=>`<div class="announcement"><small>${esc(courseName(a.courseId))}${a.posted?' · '+esc(new Date(a.posted).toLocaleDateString()):''}</small><strong><a href="${esc(safeURL(a.url))}" target="_blank" rel="noopener">${esc(a.title)}</a></strong><p class="muted">${esc(a.message.slice(0,220))}${a.message.length>220?'…':''}</p></div>`).join('')}</div>`;}
function calendarCard(){if(!calendarState)return `<div class="card"><small>Calendar export saves a file. “Add to Google/Outlook” sends the task title and time to the selected calendar service; private notes are excluded. Automatic calendar sync is available in the extension.</small></div>`;const names={google:'Google Calendar',microsoft:'Outlook',apple:'iCloud (Apple)'};const rows=Object.entries(names).map(([p,label])=>{const a=calendarState[p];const status=a?.connected?(a.error?`Error: ${esc(a.error)}`:a.lastSync?`Synced ${esc(new Date(a.lastSync).toLocaleString())}`:'Connected, waiting for first sync'):configured[p]?'Not connected':'Not configured in this build';return `<div class="row between"><div><strong>${label}</strong><br><small>${status}</small></div>${a?.connected?btn('Disconnect','cal-disconnect',p,'ghost'):configured[p]?btn('Connect','cal-connect',p,'ghost'):''}</div>`;}).join('');return `<div class="card"><div class="row between"><h2>Calendar sync</h2>${Object.values(calendarState).some(a=>a?.connected)?btn('Sync now','cal-sync','','ghost'):''}</div><p class="muted">Connected calendars get a CourseLark calendar with each open task’s title, time and assignment link, updated every few minutes. Private notes stay on this device. Requests go directly from this browser to the provider; there is no CourseLark server.</p>${rows}</div>`;}
async function calendarSyncNow(){const r=await chrome.runtime.sendMessage({type:'CALENDAR_SYNC'});calendarState=await readSync();draw();const failed=Object.values(r.results||{}).filter(x=>!x.ok);if(!r.ok||failed.length)throw Error(r.error||failed.map(x=>x.error).join(' '));toast('Calendars synced.');}
