function courseEditor(id){const c=state.courses.find(c=>c.id===id)||{id:uid(),name:'',credits:3,goal:90,grade:null,rigor:0};modal(`<h2>${id?'Manage class':'New class'}</h2><form id="course-form" data-id="${esc(c.id)}" class="form-grid"><label class="wide">Class name<input name="name" value="${esc(c.name)}" required></label><label>Course code<input name="code" value="${esc(c.code)}"></label><label>Credit hours<input name="credits" type="number" min="0" step=".5" value="${esc(c.credits)}" required></label><label>Current grade (%)<input name="grade" type="number" min="0" max="200" step=".01" value="${esc(c.grade??'')}"></label><label>Grade goal (%)<input name="goal" type="number" min="0" max="100" value="${esc(c.goal)}" required></label><label>High-school rigor bonus<select name="rigor">${[0,.5,1].map(r=>`<option value="${r}" ${Number(c.rigor)===r?'selected':''}>${r===0?'Standard':r===.5?'Honors (+0.5)':'AP / IB (+1)'}</option>`).join('')}</select></label><label>Class link<input name="url" type="url" value="${esc(c.url)}"></label><div class="wide row actions">${id?btn('Delete class','course-delete',id,'danger'):''}<button>Save class</button></div></form>`);}
async function taskPreview(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;modal(`<h2>${esc(t.title)}</h2><p class="muted">${esc(courseName(t.courseId))} · ${dateLabel(t.due)}</p><p style="white-space:pre-wrap">${esc(t.notes)}</p><div id="assignment-description"></div>${t.subtasks?.length?`<h3>Subtasks</h3>${t.subtasks.map((s,i)=>`<label class="check" style="margin:8px 0"><input type="checkbox" data-subtask="${esc(t.id)}" data-index="${i}" ${s.done?'checked':''}>${esc(s.title)}</label>`).join('')}`:''}${safeURL(t.url)?`<p><a href="${esc(safeURL(t.url))}" target="_blank" rel="noopener">Open assignment ↗</a></p>`:''}`);
 // Convert LMS HTML to text. Nothing from an assignment executes in this extension.
 const parsed=new DOMParser().parseFromString(t.description||'','text/html');parsed.querySelectorAll('script,style').forEach(n=>n.remove());document.querySelector('#assignment-description').textContent=parsed.body.textContent;}
function noteEditor(id){const n=state.notes.find(n=>n.id===id)||{id:uid(),title:'',body:'',files:[]};modal(`<h2>Notebook</h2><form id="note-form" data-id="${esc(n.id)}"><div class="form-grid"><label>Title<input name="title" value="${esc(n.title)}" required></label><label>Class<select name="courseId">${courseOptions(n.courseId)}</select></label><label class="wide">Notes<textarea name="body" id="note-body" style="min-height:240px">${esc(n.body)}</textarea></label></div><div class="row" style="margin:14px 0">${btn('Import text / PDF','note-upload',n.id,'ghost')}${btn('Record audio','note-record',n.id,'ghost')}${btn('Stop recording','note-stop',n.id,'ghost')}${btn('Smart notes (AI)','note-ai',n.id,'ghost')}${btn('AI study set','note-ai-study',n.id,'ghost')}${btn('Ask about notes','note-chat',n.id,'ghost')}</div><p class="muted">Record only when you have the permissions required by law and your school or instructor. This tool does not grant permission to record or share another person’s voice or course material.</p><label class="check"><input id="browser-transcription" type="checkbox"> Also transcribe with browser speech recognition (optional; audio may be sent to your browser provider)</label><p id="record-status" role="status"></p><div class="file-list">${n.files.map(f=>`<div class="row between"><small>${esc(f.name)}</small><div>${btn('Open','file-open',f.id,'ghost')}${btn('Export','file-export',f.id,'ghost')}${btn('Delete','file-delete',f.id,'ghost')}</div></div>`).join('')}</div><div class="row actions">${id?btn('Delete note','note-delete',id,'danger'):''}<button>Save notebook</button></div></form>`);}
async function saveNote(){const form=document.querySelector('#note-form');if(!form)return null;const v=formValues(form),id=form.dataset.id;let n=state.notes.find(n=>n.id===id);if(!n){n={id,files:[]};state.notes.push(n);}Object.assign(n,v,{updated:Date.now()});await persist();return n;}
function setEditor(id){const s=state.sets.find(s=>s.id===id)||{id:uid(),title:'',cards:[]};modal(`<h2>Study set</h2><form id="set-form" data-id="${esc(s.id)}"><div class="form-grid"><label>Title<input name="title" required value="${esc(s.title)}"></label><label>Class<select name="courseId">${courseOptions(s.courseId)}</select></label><label class="wide">Term : definition (one per line)<textarea name="cards" rows="12" required placeholder="Mitosis : Cell division producing two genetically identical cells">${esc(s.cards.map(c=>c.front+' : '+c.back).join('\n'))}</textarea></label></div><p class="muted">Unlimited sets and cards. Use a colon between each term and definition.</p><div class="row actions">${id?btn('Delete set','set-delete',id,'danger'):''}<button>Save study set</button></div></form>`);}
let currentStudy,studyMode;
function showStudy(id,mode,reset=true){currentStudy=state.sets.find(s=>s.id===id);if(!currentStudy?.cards.length)return toast('Add cards first.');studyMode=mode;if(reset){studyIndex=0;studyFlipped=false;currentStudy.sessions=(currentStudy.sessions||0)+1;persist();}quizAnswered=false;const c=currentStudy.cards[studyIndex%currentStudy.cards.length];
 const shuffled=[c,...currentStudy.cards.filter(x=>x.id!==c.id).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);
 modal(`<h2>${esc(currentStudy.title)}</h2><small>${mode==='flash'?'Flashcards':'Practice quiz'} · ${studyIndex%currentStudy.cards.length+1} of ${currentStudy.cards.length}</small>${mode==='flash'?`<div class="flashcard card" data-action="flash-flip" tabindex="0" role="button">${esc(studyFlipped?c.back:c.front)}</div><small>Click or press Space to flip.</small><div class="row actions">${btn('← Previous','study-prev')}${btn('Got it →','study-next','','')}</div>`:`<h3 style="margin-top:24px">${esc(c.front)}</h3><div id="quiz-answers">${shuffled.map(a=>`<button class="answer" data-action="quiz-answer" data-id="${esc(a.id)}">${esc(a.back)}</button>`).join('')}</div><p id="quiz-feedback" role="status"></p><div class="row actions">${btn('Next question →','study-next','','')}</div>`}`);}
async function localAI(prompt,context){const token=await readCompanionToken();if(!token)throw Error('Start the companion and enter its pairing code in Settings first.');if(context&&!confirm('Send these notes and your prompt to your Ollama service? Ollama may use a cloud model depending on your configuration.'))throw Error('AI request canceled.');const response=await fetch('http://127.0.0.1:4317/api/chat',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({model:state.settings.model,prompt,context})});const data=await response.json();if(!response.ok)throw Error(data.error||'AI request failed.');return data.text;}
async function pickFile(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>resolve(input.files[0]);input.oncancel=()=>resolve(null);input.click();});}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function safeTheme(t){return normalizeTheme(t).theme;}
