 if(action==='quiz-answer'){if(quizAnswered)return;quizAnswered=true;const card=currentStudy.cards[studyIndex%currentStudy.cards.length],correct=id===card.id;document.querySelectorAll('#quiz-answers button').forEach(b=>{b.classList.add(b.dataset.id===card.id?'correct':b.dataset.id===id?'wrong':'neutral');});document.querySelector('#quiz-feedback').textContent=correct?'Correct. '+card.back:'Review: '+card.back;if(correct){recordActivity(state,'study',currentStudy.id+':'+dayKey()+':quiz:'+studyIndex);await persist();}return;}
 if(action.startsWith('game-')){const s=state.sets.find(s=>s.id===id);if(s.cards.length<3)throw Error('Games need at least three cards.');modal(`<h2>${esc(s.title)}</h2><div id="game"></div>`);return startGame(document.querySelector('#game'),action.slice(5),s.cards,{onScore:async score=>{const key=s.id+':'+action;state.scores[key]=Math.max(state.scores[key]||0,score);recordActivity(state,'study',uid());await persist();},highScore:state.scores[s.id+':'+action]||0});}
 if(action==='theme-apply')return applySelectedTheme([...themes,...state.themes].find(t=>t.id===id));if(action==='theme-history')return applySelectedTheme(state.themeHistory[Number(id)]);
 if(action==='theme-export-better'){const t=[...themes,...state.themes].find(t=>t.id===id);return download('bettercampus-theme.json',JSON.stringify(exportBetterCampus(t,state.settings),null,2));}
 if(action==='theme-export'){const t=[...themes,...state.themes].find(t=>t.id===id);return download('open-campus-theme.json',JSON.stringify({...t,settings:{...t.settings,...displaySnapshot()}},null,2));}
 if(action==='theme-paste'){modal('<h2>Import theme JSON</h2><form id="theme-paste-form"><label>Paste a BetterCampus or CourseLark export<textarea name="json" required rows="10"></textarea></label><button>Preview import</button></form>');return;}
 if(action==='theme-community')return openCommunity();
 if(action==='community-preview'){toast('Loading community theme…');return previewThemeImport(await communityRequest(id));}
 if(action==='theme-install'){if(!pendingTheme)return;state.themes.push(pendingTheme);await applySelectedTheme(pendingTheme);pendingTheme=null;dialog.close();toast('Theme installed.');return;}
 if(action==='theme-import'){const f=await pickFile('.json');if(!f)return;if(f.size>1000000)throw Error('Theme file must be under 1 MB.');return previewThemeImport(normalizeTheme(JSON.parse(await f.text())));}
 if(action==='backup-export')return download('open-campus-backup.json',JSON.stringify(state,null,2));
 if(action==='backup-import'){const f=await pickFile('.json');if(!f)return;if(!confirm('Replace local data with this backup? Export your current data first if needed. Stored attachments absent from the backup will be removed.'))return;const imported=mergeImport(state,JSON.parse(await f.text()));const present=new Set(await fileKeys());let missing=0;for(const note of imported.notes){note.files=note.files.filter(file=>{const found=present.has(file.id);if(!found)missing++;return found;});}state=imported;await persist(true);const retained=state.notes.flatMap(note=>note.files.map(file=>file.id));const removed=await filePrune(retained);toast(`Backup restored. ${removed} unreferenced attachments removed.${missing?` ${missing} unavailable attachment references removed.`:''}`);return;}
 if(action==='data-clear'){if(!confirm('Permanently erase this app’s tasks, notes, grades, settings, and attachments from this browser profile? Export a backup first if needed. This does not erase exported copies or standalone data in another browser origin.'))return;const origins=state.settings.lmsOrigins||[];state=initial();await persist(true);await fileClear();await writeCompanionToken('');if(calendarState){await clearSync();calendarState={};await clearDeviceSync();}localStorage.removeItem('campus-focus');focusTimer=null;if(globalThis.chrome?.permissions&&origins.length)await chrome.permissions.remove({origins:origins.map(origin=>origin+'/*')});if(globalThis.chrome?.runtime)await chrome.runtime.sendMessage({type:'REGISTER'});toast('Local app data and attachments erased.');return;}
 if(action==='ai-test'){const text=await localAI('Reply with: AI is ready.','');return toast(text);}
 if(action==='audio-transcribe'){const token=await readCompanionToken();if(!token)throw Error('Start the companion and enter its pairing code in Settings first.');const f=await fileGet(id);toast('Local transcription is running…');const response=await fetch('http://127.0.0.1:4317/api/transcribe',{method:'POST',headers:{'Content-Type':f.type,Authorization:'Bearer '+token},body:f.blob});const result=await response.json();if(!response.ok)throw Error(result.error);const n=state.notes.find(n=>n.files.some(f=>f.id===id));if(n){n.body+='\n\n'+result.text;await persist();}document.querySelector('#audio-result').textContent=result.text;return;}
 if(action==='disconnect'){if(globalThis.chrome?.permissions)await chrome.permissions.remove({origins:[id+'/*']});state.settings.lmsOrigins=state.settings.lmsOrigins.filter(o=>o!==id);await persist(true);if(globalThis.chrome?.runtime)await chrome.runtime.sendMessage({type:'REGISTER'});return;}
 if(action==='timer-toggle'){if(!focusTimer)focusTimer={id:uid(),remaining:state.settings.focusMinutes*60,kind:'focus'};if(focusTimer.running){focusTimer.remaining=Math.max(0,Math.ceil((focusTimer.end-Date.now())/1000));focusTimer.running=false;}else {if(focusTimer.remaining<=0)focusTimer.remaining=state.settings.focusMinutes*60;focusTimer.end=Date.now()+focusTimer.remaining*1000;focusTimer.running=true;}saveTimer();return;}
 if(action==='timer-reset'||action==='timer-break'){focusTimer={id:uid(),remaining:(action==='timer-break'?state.settings.breakMinutes:state.settings.focusMinutes)*60,running:false,kind:action==='timer-break'?'break':'focus'};saveTimer();return;}
 if(action==='breath'){clearInterval(breathingInterval);state.settings.breathSeconds=Math.max(8,Math.min(600,Number(document.querySelector('#breath-duration').value)||60));await persist();breathingEnd=Date.now()+state.settings.breathSeconds*1000;const circle=document.querySelector('#breath-circle');circle.classList.add('breathing');const start=Date.now();breathingInterval=setInterval(()=>{const label=document.querySelector('#breath-label');if(!label){clearInterval(breathingInterval);return;}const secs=Math.max(0,Math.ceil((breathingEnd-Date.now())/1000));label.textContent=((Date.now()-start)%8000<4000?'Breathe in':'Breathe out')+' · '+secs+'s';if(!secs){clearInterval(breathingInterval);circle.classList.remove('breathing');label.textContent='A little more room to think.';}},250);return;}
 if(action==='pdf-prev'||action==='pdf-next'){pdfState.page=Math.max(1,Math.min(pdfState.pdf.numPages,pdfState.page+(action==='pdf-next'?1:-1)));return renderPDF();}
